CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_booking_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.booking_status IS DISTINCT FROM NEW.booking_status THEN
        INSERT INTO booking_status_history (booking_id, previous_status, new_status)
        VALUES (NEW.booking_id, OLD.booking_status, NEW.booking_status);
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  assigned_role public.user_role;
  user_full_name text;
  user_phone text;
BEGIN
  -- Safely extract metadata passed from Flutter
  user_full_name := COALESCE(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1));
  user_phone := new.raw_user_meta_data->>'phone';
  
  -- Safe role casting with fallback to 'customer'
  BEGIN
    assigned_role := (new.raw_user_meta_data->>'role')::public.user_role;
  EXCEPTION WHEN OTHERS THEN
    assigned_role := 'customer'::public.user_role;
  END;
  
  IF assigned_role IS NULL THEN
    assigned_role := 'customer'::public.user_role;
  END IF;

  -- Insert or update public.users
  INSERT INTO public.users (
    user_id,
    email,
    phone,
    full_name,
    role,
    is_active
  )
  VALUES (
    new.id,
    new.email,
    user_phone,
    user_full_name,
    assigned_role,
    true
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    full_name = EXCLUDED.full_name,
    phone = EXCLUDED.phone,
    email = EXCLUDED.email;

  -- Create corresponding profile depending on role
  IF assigned_role = 'customer' THEN
    INSERT INTO public.customer_profiles (user_id, service_preferences)
    VALUES (new.id, '{}')
    ON CONFLICT (user_id) DO NOTHING;
  ELSIF assigned_role = 'provider' THEN
    INSERT INTO public.provider_profiles (user_id, business_name, verification_status)
    VALUES (new.id, user_full_name, 'Pending')
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  RETURN new;
EXCEPTION WHEN OTHERS THEN
  -- Prevent trigger failure from aborting Auth user creation
  RAISE WARNING 'handle_new_user error: %', SQLERRM;
  RETURN new;
END;
$function$
